import appInfo from '../package.json';
import React, {useState,useEffect,useMemo,useRef,useCallback} from 'react';
import {Check,CheckCheck,CheckSquare,Sun,CalendarDays,Calendar,Inbox,Layers,Hash,Plus,Search,Settings,MoreHorizontal,ChevronDown,ChevronRight,ChevronLeft,ArrowUpDown,PanelRightClose,PanelRightOpen,Flag,Repeat2,Trash2,RotateCcw,Clock,Timer,Play,Pause,Square,Flame,Leaf,BookOpen,Coffee,Target,Download,Upload,X,LayoutGrid,List,Grid2X2,ArrowRight,CheckCircle2,Bell,FileText,Briefcase,House,Command,SlidersHorizontal,ExternalLink,AlertCircle,ShieldCheck,FolderPlus,Copy,HelpCircle} from 'lucide-react';
import {createInitialState,localDate,validateState,reducer,selectTasks} from './model.js';
