const IS_MAC=desktop?.platform==='darwin'||(!desktop&&/Mac/.test(navigator.platform));
const MOD_KEY=IS_MAC?'⌘':'Ctrl';
const WEEK=['一','二','三','四','五','六','日'];
const PALETTES={blue:'#3e63dd',green:'#267d6b',violet:'#7255c5',amber:'#a56b1d',rose:'#bd4b69'};
const PRIORITIES=['无优先级','低优先级','中优先级','高优先级'];
const VIEWS={today:'今天',upcoming:'最近 7 天',inbox:'收集箱',all:'所有任务',completed:'已完成',trash:'废纸篓',calendar:'日历',matrix:'四象限',focus:'专注',habits:'习惯'};
const uid=()=>crypto.randomUUID();
const dateAt=(s)=>new Date(`${s}T12:00:00`);
const shiftDate=(date,n)=>{const d=typeof date==='string'?dateAt(date):new Date(date); d.setDate(d.getDate()+n);return localDate(d);};
const prettyDate=(s)=>{if(!s)return '未设置'; const today=localDate(new Date()); if(s===today)return '今天';if(s===shiftDate(today,1))return '明天';if(s===shiftDate(today,-1))return '昨天';return dateAt(s).toLocaleDateString('zh-CN',{month:'long',day:'numeric'});};
const dateLabel=(d)=>d.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});
const isMainView=(view)=>['calendar','matrix','focus','habits'].includes(view);
const IconButton=({icon:Icon,label,onClick,active=false,...props})=><button className={`icon-button ${active?'active':''}`} aria-label={label} title={label} onClick={onClick} {...props}><Icon size={17} strokeWidth={1.65}/></button>;
const Badge=({children,color})=><span className="tag" style={color?{color,background:`${color}12`}:undefined}>{children}</span>;

function Modal({title,children,onClose,wide=false}) {
 const ref=useRef(), closeRef=useRef(onClose); closeRef.current=onClose;
 useEffect(()=>{const previous=document.activeElement;const handle=e=>{if(e.key==='Escape')closeRef.current(); if(e.key==='Tab'){const els=ref.current?.querySelectorAll('button,input,select,textarea,[tabindex="0"]');if(!els?.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}};document.addEventListener('keydown',handle);(ref.current?.querySelector('input,textarea,select')||ref.current?.querySelector('button'))?.focus();return()=>{document.removeEventListener('keydown',handle);previous?.focus?.();};},[]);
 return <div className="overlay" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section ref={ref} role="dialog" aria-modal="true" aria-label={title} className={`modal ${wide?'wide':''}`}><header><h2>{title}</h2><IconButton icon={X} label="关闭弹窗" onClick={onClose}/></header>{children}</section></div>;
}

export default function App(){
 const [state,setState]=useState(null),[loadError,setLoadError]=useState(''),[saveError,setSaveError]=useState(''),[saved,setSaved]=useState(true);
 const [workspace]=useState(()=>readWorkspace(localStorage));
 const [view,setView]=useState(workspace?.view||'today'),[selected,setSelected]=useState(workspace?.selected||null),[query,setQuery]=useState(''),[mode,setMode]=useState(workspace?.mode||'list'),[sort,setSort]=useState(workspace?.sort||'default');
 const [menu,setMenu]=useState(null),[multiSelect,setMultiSelect]=useState(false),[selectedIds,setSelectedIds]=useState([]),[quickText,setQuickText]=useState('');
 const selectionAnchor=useRef(null),bodyRef=useRef(null),scrolls=useRef(workspace?.scrolls||{}),restoringScroll=useRef(false),workspaceReady=useRef(false); 
 const [modal,setModal]=useState(null),[toast,setToast]=useState(null),[showCompleted,setShowCompleted]=useState(workspace?.showCompleted||false),[detailOpen,setDetailOpen]=useState(workspace?.detailOpen??true);
 const [now,setNow]=useState(new Date()),[searchOpen,setSearchOpen]=useState(false);
 const [timer,setTimer]=useState(()=>{try{const t=JSON.parse(localStorage.getItem('shixu-timer'));return t&&typeof t.id==='string'&&['focus','break'].includes(t.kind)&&Number.isFinite(t.total)&&t.total>=60&&t.total<=10800&&Number.isFinite(t.remaining)&&t.remaining>=0&&t.remaining<=t.total&&(!t.endAt||Number.isFinite(t.endAt))?t:null;}catch{return null;}}); const finishedTimers=useRef(new Set()); const quickRef=useRef(),mounted=useRef(false),latest=useRef(null),saveCounter=useRef(0);
 useEffect(()=>{let live=true;loadState().then(data=>{if(live){const initial=data?validateState(data):createInitialState();setState(initial);setView(validWorkspaceView(initial,workspace?.view));setSelected(initial.tasks.some(t=>t.id===workspace?.selected)?workspace.selected:(selectTasks(initial,validWorkspaceView(initial,workspace?.view))[0]?.id??null));workspaceReady.current=true;}}).catch(e=>live&&setLoadError(e.message));return()=>{live=false;};},[]);
 useEffect(()=>{const interval=setInterval(()=>setNow(new Date()),1000);return()=>clearInterval(interval);},[]);
 const showToast=useCallback((message,undo)=>setToast({id:uid(),message,undo}),[]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(null),5500);return()=>clearTimeout(timer);},[toast]);
 useEffect(()=>{if(!state)return;latest.current=state;const id=++saveCounter.current;setSaved(false);saveState(state).then(()=>{if(id===saveCounter.current){setSaved(true);setSaveError('');}}).catch(e=>{if(id===saveCounter.current)setSaveError(e.message);});},[state]);
 const act=useCallback(action=>{setState(current=>{try{return reducer(current,action);}catch(e){setTimeout(()=>showToast(e.message),0);return current;}});},[showToast]);
 useEffect(()=>{localStorage.setItem('shixu-timer',JSON.stringify(timer));},[timer]);
 useEffect(()=>{if(!state||!timer?.endAt||timer.endAt>now.getTime()||finishedTimers.current.has(timer.id))return;finishedTimers.current.add(timer.id);if(timer.kind==='focus'){act({type:'FOCUS_ADD',session:{id:timer.id,taskId:state.tasks.some(t=>t.id===timer.taskId)?timer.taskId:null,minutes:timer.total/60,endedAt:new Date(timer.endAt).toISOString()}});showToast('专注完成，休息一下吧');notify('这一段专注，完成了','给自己一点休息，再从容出发。').catch(()=>{});}else showToast('休息结束，准备好再次出发');setTimer(null);},[timer,now,state,act,showToast]);
 const navigate=useCallback(v=>{setView(v);setQuery('');setSelectedIds([]);setMultiSelect(false);selectionAnchor.current=null;setMenu(null);},[]);
 const closeMenu=useCallback(()=>setMenu(null),[]);
 const closeModal=useCallback(()=>setModal(null),[]);

 useEffect(()=>{if(!state)return;const actual=state.settings.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):state.settings.theme;document.documentElement.dataset.theme=actual;document.documentElement.style.setProperty('--accent',PALETTES[state.settings.accent]||PALETTES.blue);},[state?.settings]);
 const task=state?.tasks.find(t=>t.id===selected);
 const listName=state?.lists.find(l=>`list:${l.id}`===view)?.name;
 const title=VIEWS[view]||listName||(view.startsWith('tag:')?`# ${view.slice(4)}`:'所有任务');
 const today=localDate(now);
 const tasks=useMemo(()=>{if(!state)return [];let items=selectTasks(state,isMainView(view)?'all':view,query);if(sort==='priority')items=[...items].sort((a,b)=>b.priority-a.priority);if(sort==='date')items=[...items].sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));if(sort==='created')items=[...items].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return items;},[state,view,query,sort,today]);
 useEffect(()=>{if(state){const valid=validWorkspaceView(state,view);if(valid!==view)navigate(valid);}},[state,view,navigate]);
 const counts=useMemo(()=>{if(!state)return {};return Object.fromEntries(['today','upcoming','inbox','all','completed','trash',...state.lists.map(l=>`list:${l.id}`)].map(v=>[v,selectTasks(state,v).length]));},[state,today]);
 const toggleTask=(t)=>performTaskAction('complete',{},[t.id]);
 const removeTask=(t)=>{act({type:'TASK_DELETE',id:t.id});showToast('已移到废纸篓',{type:'TASK_RESTORE',id:t.id});};
 const updateTask=(id,patch)=>act({type:'TASK_UPDATE',id,patch});
 const addTask=(data,{reveal=true}={})=>{const id=uid();try{reducer(state,{type:'TASK_ADD',task:{id,...data}});}catch(e){showToast(e.message);return null;}act({type:'TASK_ADD',task:{id,...data}});if(reveal){setSelected(id);setDetailOpen(true);}showToast('任务已添加');return id;};
 const quickAdd=(text)=>{if(!text.trim())return false;try{const data=parseQuickTask(text,{due:view==='today'?today:'',listId:view.startsWith('list:')?view.slice(5):'inbox',tags:view.startsWith('tag:')?[view.slice(4)]:[]});return !!addTask(data,{reveal:false});}catch(e){showToast(e.message);return false;}};
 const quickPreview=useMemo(()=>{if(!quickText.trim())return '';try{const data=parseQuickTask(quickText,{due:view==='today'?today:''});return [data.due&&prettyDate(data.due),data.reminder&&new Date(data.reminder).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),data.priority>0&&PRIORITIES[data.priority],...data.tags.map(t=>'#'+t)].filter(Boolean).join(' · ');}catch(e){return e.message;}},[quickText,view,today]);
 const selectedTasks=state?state.tasks.filter(t=>selectedIds.includes(t.id)):[];
 const openTaskMenu=(kind,ids,event)=>{event?.preventDefault();const rect=event?.currentTarget?.getBoundingClientRect();setMenu({kind,ids,x:event?.type==='contextmenu'?event.clientX:rect?.left??200,y:event?.type==='contextmenu'?event.clientY:(rect?.bottom??180)+5});};
 const onRowSelect=(id,event)=>{
   if(event&&(event.metaKey||event.ctrlKey||event.shiftKey||multiSelect)){
     setMultiSelect(true);
     if(event.shiftKey&&selectionAnchor.current){const order=[...document.querySelectorAll('.main-area .task-row')].filter(el=>el.getClientRects().length).map(el=>el.dataset.taskId),a=order.indexOf(selectionAnchor.current),b=order.indexOf(id);if(a>=0&&b>=0)setSelectedIds(order.slice(Math.min(a,b),Math.max(a,b)+1));else setSelectedIds([id]);}
     else setSelectedIds(previous=>previous.includes(id)?previous.filter(v=>v!==id):[...previous,id]);
     if(!event.shiftKey)selectionAnchor.current=id;
     setSelected(id);return true;
   }
   selectionAnchor.current=id;setSelectedIds([]);setSelected(id);setDetailOpen(true);return false;
 };
 const copyTask=t=>{const id=uid();act({type:'TASK_ADD',task:{...t,id,title:`${t.title}（副本）`,createdAt:new Date().toISOString(),completed:false,completedAt:null,deleted:false,subtasks:t.subtasks.map(item=>({...item,id:uid()}))}});showToast('任务已复制');};
 const performTaskAction=(operation,patch={},ids=menu?.ids||selectedIds)=>{
   setMenu(null);const items=state.tasks.filter(t=>ids.includes(t.id));if(!items.length)return;
   if(operation==='copy'){copyTask(items[0]);return;}
   if(operation==='focus'){navigate('focus');if(timer){showToast('已有计时，已返回专注');}else{sessionStorage.setItem('shixu-focus-task',items[0].id);setTimer({id:uid(),kind:'focus',taskId:items[0].id,total:state.settings.focusMinutes*60,remaining:state.settings.focusMinutes*60,endAt:Date.now()+state.settings.focusMinutes*60000});}return;}
   if(operation==='purge'){setModal({type:'purge-selected',ids:items.map(t=>t.id)});return;}
   const actions=items.filter(t=>operation!=='complete'||t.completed===items[0].completed).map(t=>operation==='update'?{type:'TASK_UPDATE',id:t.id,patch}:{type:({complete:'TASK_TOGGLE',delete:'TASK_DELETE',restore:'TASK_RESTORE'})[operation],id:t.id});
   if(!actions.length)return;
   try{const after=reducer(state,{type:'TASK_BATCH',actions});const originals=new Map(state.tasks.map(t=>[t.id,t]));const changed=after.tasks.filter(t=>JSON.stringify(originals.get(t.id))!==JSON.stringify(t));const changedIds=new Set(changed.map(t=>t.id));const before=state.tasks.filter(t=>changedIds.has(t.id));
     setState(after);setSelectedIds([]);setMultiSelect(false);
     showToast(operation==='delete'?`已将 ${items.length} 项任务移到废纸篓`:operation==='restore'?`已恢复 ${items.length} 项任务`:operation==='complete'?`已更新 ${actions.length} 项任务的完成状态`:`已更新 ${items.length} 项任务`,{type:'TASK_REVERT',before,after:changed});
   }catch(e){showToast(e.message);}
 };
 const persistWorkspace=useCallback(()=>{if(!workspaceReady.current)return;writeWorkspace(localStorage,{view,selected,mode,sort,detailOpen,showCompleted,scrolls:scrolls.current});},[view,selected,mode,sort,detailOpen,showCompleted]);
 useEffect(()=>{persistWorkspace();},[persistWorkspace]);
 useEffect(()=>{const handler=()=>persistWorkspace();window.addEventListener('pagehide',handler);return()=>window.removeEventListener('pagehide',handler);},[persistWorkspace]);
 useEffect(()=>{if(!state||!bodyRef.current)return;restoringScroll.current=true;bodyRef.current.scrollTop=scrolls.current[view]||0;const frame=requestAnimationFrame(()=>{restoringScroll.current=false;});return()=>cancelAnimationFrame(frame);},[view,!!state]);
 useEffect(()=>{if(!state)return;setSelectedIds(ids=>ids.filter(id=>tasks.some(t=>t.id===id)));},[state,view]);
 const shortcutRef=useRef(null);
 shortcutRef.current={state,view,tasks,selected,multiSelect,selectedIds,menu,modal,searchOpen,onRowSelect,toggleTask,performTaskAction,navigate};
 useEffect(()=>{const listener=e=>{
   const current=shortcutRef.current;if(e.isComposing)return;
   if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setMenu(null);setModal(null);setSearchOpen(v=>!v);return;}
   if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='n'){e.preventDefault();setMenu(null);setSearchOpen(false);setModal({type:'task'});return;}
   if(e.key==='Escape'){setSearchOpen(false);setModal(null);setMenu(null);setSelectedIds([]);setMultiSelect(false);return;}
   if(!current.state||current.modal||current.searchOpen||current.menu||isMainView(current.view)||e.target.closest('input,textarea,select,[contenteditable=true]'))return;
   if(e.target.closest('button,a,[role=checkbox]')&&!e.target.closest('.task-content'))return;
   const rows=[...document.querySelectorAll('.main-area .task-row')].filter(el=>el.getClientRects().length&&getComputedStyle(el).visibility!=='hidden');
   if(!rows.length)return;
   if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='a'){e.preventDefault();setMultiSelect(true);setSelectedIds(rows.map(el=>el.dataset.taskId));return;}
   if(['ArrowDown','ArrowUp'].includes(e.key)){
     e.preventDefault();const at=rows.findIndex(el=>el.dataset.taskId===current.selected),index=at<0?(e.key==='ArrowDown'?0:rows.length-1):Math.max(0,Math.min(rows.length-1,at+(e.key==='ArrowDown'?1:-1)));const row=rows[index];
     if(e.shiftKey)current.onRowSelect(row.dataset.taskId,e);else{setSelected(row.dataset.taskId);setSelectedIds([]);selectionAnchor.current=row.dataset.taskId;}
     row.focus({preventScroll:true});row.scrollIntoView({block:'nearest'});return;
   }
   if(e.target.closest('button'))return;
   const target=current.state.tasks.find(t=>t.id===current.selected);if(!target||target.deleted)return;
   if(e.code==='Space'||e.key===' '){e.preventDefault();if(current.selectedIds.length)current.performTaskAction('complete',{},current.selectedIds);else current.toggleTask(target);return;}
   if(e.key==='Enter'){e.preventDefault();setDetailOpen(true);requestAnimationFrame(()=>{const input=document.querySelector('[aria-label="任务标题"]');input?.focus();input?.select();});}
 };window.addEventListener('keydown',listener);return()=>window.removeEventListener('keydown',listener);},[]);

 if(loadError)return <div className="startup-error"><AlertCircle size={36}/><h1>数据暂时无法读取</h1><p>{loadError}</p><p>为保护已有内容，应用已停止写入。请保留数据文件并检查备份。</p><button className="primary" onClick={()=>location.reload()}>重新读取</button></div>;
 if(!state)return <div className="startup-error"><div className="brand-mark"><CheckCheck/></div><p>正在整理你的一天…</p></div>;
 const completedToday=state.tasks.filter(t=>t.completed&&!t.deleted&&t.completedAt&&localDate(new Date(t.completedAt))===today).length;
 const todayActive=selectTasks(state,'today').length;
 const allTags=[...new Set(state.tasks.filter(t=>!t.deleted).flatMap(t=>t.tags))];
 const currentModule=['calendar','matrix','focus','habits'].includes(view)?view:'tasks';
 return <TaskActionsContext.Provider value={{multiSelect,selectedIds,onRowSelect,openTaskMenu,performTaskAction}}><div className={`app-shell ${IS_MAC?'platform-mac':'platform-windows'} ${!detailOpen?'no-detail':''}`}>
  <aside className="rail"><div className="rail-top"><div className="traffic-spacer"/><button className="brand-mark" title="拾序 · 今天" aria-label="拾序首页" onClick={()=>navigate('today')}><CheckCheck size={25} strokeWidth={2.2}/></button><div className="rail-items">{[[CheckSquare,'tasks','任务'],[CalendarDays,'calendar','日历'],[Grid2X2,'matrix','四象限'],[Timer,'focus','专注'],[Leaf,'habits','习惯']].map(([Icon,id,label])=><button key={id} className={`rail-button ${currentModule===id?'active':''}`} title={label} aria-label={label} onClick={()=>navigate(id==='tasks'?'today':id)}><Icon size={21} strokeWidth={1.7}/><span>{label}</span></button>)}</div></div><div className="rail-bottom"><IconButton icon={HelpCircle} label="使用帮助" onClick={()=>setModal({type:'help'})}/><IconButton icon={Settings} label="设置" onClick={()=>setModal({type:'settings'})}/><button className="avatar" title="本地工作空间" onClick={()=>setModal({type:'settings'})}>序</button></div></aside>
  <aside className="sidebar"><div className="workspace"><div><span className="workspace-name">我的空间<ChevronDown size={13}/></span><span className="workspace-caption">一点一滴，从容有序</span></div><IconButton icon={Plus} label="新建任务" onClick={()=>setModal({type:'task'})}/></div>
   <button className="search-trigger" onClick={()=>setSearchOpen(true)}><Search size={15}/><span>搜索</span><kbd>{MOD_KEY} K</kbd></button>
   <nav className="smart-nav" aria-label="智能清单">{[[Sun,'today'],[CalendarDays,'upcoming'],[Inbox,'inbox'],[Layers,'all']].map(([Icon,id])=><button key={id} aria-label={VIEWS[id]} className={`nav-item ${view===id?'selected':''}`} onClick={()=>navigate(id)}><Icon size={17}/><span>{VIEWS[id]}</span><span className="count">{counts[id]||''}</span></button>)}</nav>
   <div className="sidebar-scroll"><div className="side-section"><div className="side-label"><span>我的清单</span><IconButton icon={Plus} label="添加清单" onClick={()=>setModal({type:'list'})}/></div><div>{state.lists.filter(l=>l.id!=='inbox').map(l=><div className={`list-nav-wrap ${view===`list:${l.id}`?'selected':''}`} key={l.id}><button className="nav-item" onClick={()=>navigate(`list:${l.id}`)}><span className="list-square" style={{'--list-color':l.color}}/><span>{l.name}</span><span className="count">{counts[`list:${l.id}`]||''}</span></button><button className="list-more" aria-label={`编辑清单 ${l.name}`} title="编辑清单" onClick={()=>setModal({type:'list',item:l})}><MoreHorizontal size={14}/></button></div>)}</div><button className="subtle-action" onClick={()=>setModal({type:'list'})}><Plus size={14}/>新建清单</button></div>
   <div className="side-section tags-section"><div className="side-label"><span>标签</span><Hash size={13}/></div>{allTags.length?allTags.map(tag=><button key={tag} className={`nav-item tag-nav ${view===`tag:${tag}`?'selected':''}`} onClick={()=>navigate(`tag:${tag}`)}><Hash size={15}/><span>{tag}</span></button>):<span className="side-empty">在任务中添加 #标签</span>}</div></div>
   <div className="sidebar-bottom"><div className="daily-card"><span className="daily-card-icon"><Sun size={19}/></span><span><b>每一小步，都算数</b><small>留一点时间，给重要的事。</small></span></div><button className={`nav-item ${view==='completed'?'selected':''}`} onClick={()=>navigate('completed')}><CheckCircle2 size={16}/><span>已完成</span><span className="count">{counts.completed||''}</span></button><button className={`nav-item ${view==='trash'?'selected':''}`} onContextMenu={e=>openTaskMenu('trash',[],e)} onClick={()=>navigate('trash')}><Trash2 size={16}/><span>废纸篓</span><span className="count">{counts.trash||''}</span></button><div className={`save-status ${saveError?'error':''}`}><span className={`status-dot ${!saved?'pending':''}`}/>{saveError?'保存失败，请立即导出':saved?'所有更改已保存在本机':'正在保存…'}{saveError&&<button onClick={()=>exportState(state)}>导出</button>}</div></div>
  </aside>
  <main className="main-area"><div className="topbar"><div className="breadcrumb">我的空间<ChevronRight size={13}/><span>{title}</span></div><div className="topbar-actions"><span className="local-pill"><span/>本地模式</span><IconButton icon={Search} label="搜索任务" onClick={()=>setSearchOpen(true)}/><span className="toolbar-divider"/><IconButton icon={detailOpen?PanelRightClose:PanelRightOpen} label={detailOpen?'收起详情':'展开详情'} onClick={()=>setDetailOpen(v=>!v)}/></div></div>
   {saveError&&<div className="error-banner"><AlertCircle size={16}/>{saveError}<button onClick={()=>exportState(state)}>导出备份</button></div>}
   <div ref={bodyRef} onScroll={e=>{if(!restoringScroll.current){scrolls.current[view]=e.currentTarget.scrollTop;persistWorkspace();}}} className={`main-body ${isMainView(view)?'module-body':''}`}>
   <header className="page-heading"><div><div className="eyebrow">{view==='today'?dateLabel(now):'MY WORKSPACE / 拾序'}</div><h1>{view==='today'?<Sun className="sun-icon" size={31} strokeWidth={1.6}/>:view==='habits'?<Leaf size={29}/>:view==='focus'?<Timer size={29}/>:view==='calendar'?<CalendarDays size={29}/>:view==='matrix'?<Grid2X2 size={29}/>:null}{title}</h1><p>{view==='today'?`${todayActive} 件待办，专注眼前，让美好发生。`:view==='upcoming'?'提前看见安排，把时间留给重要的事。':view==='calendar'?'让计划落在日历上，给每一天留一点余地。':view==='matrix'?'分清轻重缓急，把注意力放在真正重要的事上。':view==='habits'?'好的变化，藏在每一天的小小坚持里。':view==='focus'?'一次只做一件事，进入自己的节奏。':view==='trash'?'删除的任务保留在这里，可随时恢复。':view==='completed'?'那些认真做过的小事，都是前进的痕迹。':'写下来，就为想做的事迈出了第一步。'}</p></div>{view==='today'&&<div className="today-progress"><div className="mini-week">{WEEK.map((day,i)=><span key={day} className={i===(now.getDay()+6)%7?'current':''}><small>{day}</small><i style={{height:`${[12,22,16,27,19,10,20][i]}px`}}/></span>)}</div><span><b>{completedToday}</b> 件已完成</span></div>}</header>
   {view==='calendar'?<CalendarView state={state} today={today} toggleTask={toggleTask} selected={selected} onSelect={id=>{setSelected(id);setDetailOpen(true);}} updateTask={updateTask} addTask={data=>{setModal({type:'task',defaults:data});}}/>:
    view==='matrix'?<MatrixView state={state} today={today} onSelect={id=>{setSelected(id);setDetailOpen(true);}} toggleTask={toggleTask} updateTask={updateTask}/>:
    view==='habits'?<HabitsView state={state} today={today} act={act} openModal={setModal}/>:
    view==='focus'?<FocusView state={state} now={now} act={act} showToast={showToast} timer={timer} setTimer={setTimer}/>:
    <><div className="list-toolbar"><div className="segmented"><button className={mode==='list'?'active':''} onClick={()=>setMode('list')}><List size={15}/>列表</button><button className={mode==='board'?'active':''} onClick={()=>setMode('board')}><LayoutGrid size={14}/>看板</button></div><div className="list-toolbar-right"><button className={`bulk-select-trigger ${multiSelect?'active':''}`} aria-label={multiSelect?'退出批量选择':'批量选择'} onClick={()=>{setMultiSelect(v=>!v);setSelectedIds([]);}}>{multiSelect?'完成选择':'多选'}</button>{view==='trash'&&<button className="secondary empty-trash-button" disabled={!counts.trash} onClick={()=>setModal({type:'empty-trash'})}><Trash2 size={14}/>清空废纸篓</button>}<label className="sort-control"><ArrowUpDown size={14}/><select aria-label="排序方式" value={sort} onChange={e=>setSort(e.target.value)}><option value="default">默认排序</option><option value="priority">优先级</option><option value="date">截止日期</option><option value="created">最新创建</option></select></label><IconButton icon={SlidersHorizontal} label={showCompleted?'隐藏已完成任务':'显示已完成任务'} active={showCompleted} onClick={()=>setShowCompleted(v=>!v)}/></div></div>
    {multiSelect&&<div className="bulk-toolbar" aria-label="批量任务操作"><span>已选 {selectedTasks.length} 项</span><button onClick={()=>setSelectedIds(tasks.map(t=>t.id))}>全选</button>{view==='trash'?<><button disabled={!selectedTasks.length} onClick={()=>performTaskAction('restore')}><RotateCcw size={12}/>恢复</button><button disabled={!selectedTasks.length} className="danger-text" onClick={()=>performTaskAction('purge')}><Trash2 size={12}/>永久删除</button></>:<><button disabled={!selectedTasks.length} onClick={()=>performTaskAction('complete')}><Check size={12}/>{view==='completed'?'取消完成':'完成'}</button><button disabled={!selectedTasks.length} onClick={e=>openTaskMenu('date',selectedIds,e)}><CalendarDays size={12}/>日期</button><button disabled={!selectedTasks.length} onClick={e=>openTaskMenu('move',selectedIds,e)}><Layers size={12}/>移动</button><button disabled={!selectedTasks.length} className="danger-text" onClick={()=>performTaskAction('delete')}><Trash2 size={12}/>删除</button></>}</div>}
    {!['completed','trash'].includes(view)&&<form className="quick-add" onSubmit={e=>{e.preventDefault();if(quickAdd(quickText)){setQuickText('');quickRef.current?.focus();}}}><Plus size={19}/><input ref={quickRef} onKeyDown={e=>{if(e.key==='Enter'&&(e.nativeEvent.isComposing||e.nativeEvent.keyCode===229))e.preventDefault();}} value={quickText} onChange={e=>setQuickText(e.target.value)} aria-label="快速添加任务" placeholder="添加任务，按 Enter 保存" maxLength={500}/><span className="quick-hint">明天 15:00 / !高 / #标签</span><button type="submit" title="添加任务" aria-label="添加快速任务"><ArrowRight size={16}/></button></form>}
    {quickText&&<p className="quick-help">识别结果：<strong>{quickPreview||'直接添加任务'}</strong> · Enter 连续添加，{MOD_KEY} N 详细填写</p>}
    {query&&<div className="filter-note">搜索 “{query}”<button onClick={()=>setQuery('')}><X size={14}/>清除</button></div>}
    {mode==='board'&&!['completed','trash'].includes(view)?<BoardView tasks={tasks} lists={state.lists} selected={selected} onSelect={id=>{setSelected(id);setDetailOpen(true);}} toggleTask={toggleTask} updateTask={updateTask}/>:<TaskList tasks={tasks} state={state} view={view} today={today} selected={selected} onSelect={id=>{setSelected(id);setDetailOpen(true);}} toggleTask={toggleTask} act={act} showCompleted={showCompleted} query={query} newTask={()=>setModal({type:'task'})}/>}
    <div className="list-footer"><span>{tasks.length} 件{view==='completed'?'已完成':view==='trash'?'已删除':'待办'}任务</span><span>{MOD_KEY} N 新建任务</span></div></>}
   </div>
  </main>
  {detailOpen&&<TaskDetail key={selected||'empty'} task={task} state={state} today={today} updateTask={updateTask} toggleTask={toggleTask} removeTask={removeTask} act={act} setView={navigate} close={()=>setDetailOpen(false)} showToast={showToast}/>}
  {toast&&<div className="toast" role="status"><CheckCircle2 size={17}/><span>{toast.message}</span>{toast.undo&&<button onClick={()=>{act(toast.undo);setToast(null);}}>撤销</button>}<button aria-label="关闭提示" className="toast-close" onClick={()=>setToast(null)}><X size={14}/></button></div>}
  {menu&&<TaskActionMenu key={menu.kind} menu={menu} lists={state.lists} tasks={state.tasks} onClose={closeMenu} onChangeMenu={setMenu} onAction={(operation,patch)=>{if(operation==='empty-trash'){setMenu(null);setModal({type:'empty-trash'});}else performTaskAction(operation,patch);}}/>}
  {searchOpen&&<SearchModal onCommand={id=>{setSearchOpen(false);if(id==='new-task')setModal({type:'task'});else if(id==='new-list')setModal({type:'list'});else if(id==='settings')setModal({type:'settings'});else if(id==='theme'){act({type:'SETTINGS_UPDATE',patch:{theme:document.documentElement.dataset.theme==='dark'?'light':'dark'}});showToast('外观已切换');}else if(id==='start-focus'){if(timer){navigate('focus');showToast('已有计时，已返回专注');}else{navigate('focus');setTimer({id:uid(),kind:'focus',taskId:null,total:state.settings.focusMinutes*60,remaining:state.settings.focusMinutes*60,endAt:Date.now()+state.settings.focusMinutes*60000});}}else navigate(id);}} state={state} onClose={()=>setSearchOpen(false)} onSelect={id=>{setSelected(id);setDetailOpen(true);setSearchOpen(false);}}/>}
  {modal?.type==='purge-selected'&&<Modal title="永久删除所选任务" onClose={closeModal}><div className="empty-trash-confirm"><div className="empty-trash-warning"><Trash2 size={23}/><div><h3>永久删除所选的 {modal.ids.length} 项任务？</h3><p>这些任务将被永久删除，无法撤销。专注历史记录会保留。</p></div></div><div className="modal-actions"><button className="secondary" onClick={closeModal}>取消</button><button className="primary danger-button" onClick={()=>{act({type:'TASK_BATCH',actions:modal.ids.map(id=>({type:'TASK_PURGE',id}))});if(modal.ids.includes(selected))setSelected(null);setModal(null);setSelectedIds([]);setMultiSelect(false);showToast('所选任务已永久删除');}}>永久删除所选</button></div></div></Modal>}
  {modal?.type==='empty-trash'&&<Modal title="清空废纸篓" onClose={closeModal}><div className="empty-trash-confirm"><div className="empty-trash-warning"><Trash2 size={23}/><div><h3>永久删除废纸篓中的 {counts.trash} 项任务？</h3><p>这些任务及其备注、检查事项将被永久删除，无法撤销。专注历史记录会保留。</p></div></div><div className="modal-actions"><button type="button" className="secondary" onClick={closeModal}>取消</button><button type="button" className="primary danger-button" disabled={!counts.trash} onClick={()=>{act({type:'TRASH_EMPTY'});if(task?.deleted)setSelected(null);setModal(null);showToast('废纸篓已清空');}}>永久删除全部</button></div></div></Modal>}
  {modal?.type==='task'&&<NewTaskModal state={state} today={today} defaults={{due:view==='today'?today:'',listId:view.startsWith('list:')?view.slice(5):'inbox',...modal.defaults}} onClose={closeModal} onAdd={data=>{addTask(data);setModal(null);}}/>}
  {modal?.type==='list'&&<ListModal item={modal.item} onClose={closeModal} onSave={list=>{act({type:modal.item?'LIST_UPDATE':'LIST_ADD',...(modal.item?{id:modal.item.id,patch:list}:{list})});setModal(null);}} onDelete={()=>{if(confirm('删除清单后，其中的任务将移到收集箱。继续吗？')){act({type:'LIST_DELETE',id:modal.item.id});navigate('inbox');setModal(null);}}}/>}
  {modal?.type==='habit'&&<HabitModal onClose={closeModal} onSave={habit=>{act({type:'HABIT_ADD',habit});setModal(null);}}/>}
  {modal?.type==='settings'&&<SettingsModal state={state} act={act} onClose={closeModal} showToast={showToast} onImport={data=>{act({type:'IMPORT',state:data});setSelected(null);showToast('备份已恢复');}}/>}
  {modal?.type==='help'&&<Modal title="让拾序更顺手" onClose={closeModal}><div className="help-content"><div className="help-brand"><span className="brand-mark"><CheckCheck/></span><h3>留一点秩序，给生活。</h3></div><dl><dt>{MOD_KEY} N</dt><dd>从任意页面新建任务</dd><dt>{MOD_KEY} K</dt><dd>搜索任务，或直接执行新建、专注、切换页面等操作</dd><dt>快速输入</dt><dd>“明天下午3点 开会 !高 #工作”识别日期、提醒、优先级与标签；Enter 连续添加</dd><dt>日期捷径</dt><dd>悬停任务即可改日期、优先级或删除；右键提供更多操作</dd><dt>批量处理</dt><dd>{MOD_KEY} 点击逐个多选，Shift 点击连续选取，可一起改期、移动、完成和删除</dd><dt>↑ ↓ / 空格</dt><dd>在任务列表选择与完成任务；Enter 编辑，{MOD_KEY} A 全选，Esc 退出多选</dd><dt>接着上次</dt><dd>自动记住页面、排序、看板、详情与滚动位置</dd><dt>拖动任务</dt><dd>在日历改日期，在看板改优先级，在四象限改重要性与日期</dd><dt>本地备份</dt><dd>设置 → 导出备份，可将全部任务与习惯保存为 JSON</dd></dl><p>拾序是一款独立本地应用，参考滴答清单的信息结构重新实现。云同步、协作与第三方服务暂不提供。提醒需要应用保持运行。</p></div></Modal>}
 </div></TaskActionsContext.Provider>;
}

function TaskRow({task:t,lists,selected,onSelect,toggleTask,compact=false,showDate=true}){
 const list=lists.find(l=>l.id===t.listId),actions=useTaskActions();
 const bulkSelected=actions?.selectedIds.includes(t.id);
 return <div tabIndex={0} data-task-id={t.id} aria-label={`任务 ${t.title}`} onContextMenu={e=>actions?.openTaskMenu('context',bulkSelected?actions.selectedIds:[t.id],e)} onKeyDown={e=>{if(e.key==='ContextMenu'||(e.shiftKey&&e.key==='F10')){e.preventDefault();actions?.openTaskMenu('context',bulkSelected?actions.selectedIds:[t.id],e);}}} className={`task-row ${bulkSelected?'multi-selected':''} ${selected?'is-selected':''} ${t.completed?'is-completed':''} ${compact?'compact':''}`} draggable={!t.completed&&!t.deleted} onDragStart={e=>{e.dataTransfer.setData('text/plain',t.id);e.dataTransfer.effectAllowed='move';}}>
 {actions?.multiSelect&&<button className="selection-box" role="checkbox" aria-checked={!!bulkSelected} aria-label={`选择 ${t.title}`} onClick={e=>actions.onRowSelect(t.id,e)}>{bulkSelected&&<Check size={11}/>}</button>}
 <button className={`check-box priority-${t.priority} ${t.completed?'checked':''}`} aria-label={`${t.completed?'取消完成':'完成'} ${t.title}`} onClick={()=>toggleTask(t)}>{t.completed&&<Check size={12} strokeWidth={2.7}/>}</button>
 <button className="task-content" onClick={e=>{if(actions&&(e.metaKey||e.ctrlKey||e.shiftKey||actions.multiSelect))actions.onRowSelect(t.id,e);else{actions?.onRowSelect(t.id,e);onSelect(t.id);}}}><span className="task-title">{t.title}</span><span className="task-meta">{list&&<span className="task-list-label"><i style={{background:list.color}}/>{list.name}</span>}{t.subtasks.length>0&&<span><CheckSquare size={11}/>{t.subtasks.filter(s=>s.completed).length}/{t.subtasks.length}</span>}{t.notes&&<FileText size={11}/>} {t.tags.slice(0,2).map(tag=><span className="task-tag" key={tag}>#{tag}</span>)}</span></button>
 {actions&&<div className="row-tools">{t.deleted?<IconButton icon={RotateCcw} label={`恢复 ${t.title}`} onClick={()=>actions.performTaskAction('restore',{},[t.id])}/>:<><IconButton icon={CalendarDays} label={`调整日期 ${t.title}`} onClick={e=>actions.openTaskMenu('date',[t.id],e)}/><IconButton icon={Flag} label={`调整优先级 ${t.title}`} onClick={e=>actions.openTaskMenu('priority',[t.id],e)}/><IconButton icon={Trash2} label={`删除 ${t.title}`} onClick={()=>actions.performTaskAction('delete',{},[t.id])}/></>}</div>}
 <span className="task-end">{t.repeat!=='none'&&<Repeat2 size={13}/>} {showDate&&t.due&&<span className={t.due<localDate(new Date())&&!t.completed?'overdue':''}>{prettyDate(t.due)}</span>}{t.priority>0&&<Flag size={13} className={`flag priority-${t.priority}`} fill="currentColor"/>}</span>
 </div>;
}
function TaskList({tasks,state,view,today,selected,onSelect,toggleTask,act,showCompleted,query,newTask}){
 const [collapsed,setCollapsed]=useState({});
 let groups=[];
 if(view==='today') {const overdue=tasks.filter(t=>t.due&&t.due<today),current=tasks.filter(t=>!t.due||t.due>=today);if(overdue.length)groups.push({name:'已过期',tasks:overdue,overdue:true});groups.push({name:'今天的安排',tasks:current});}
 else if(view==='upcoming'){groups=[...new Set(tasks.map(t=>t.due))].sort().map(d=>({name:`${prettyDate(d)} · 星期${WEEK[(dateAt(d).getDay()+6)%7]}`,tasks:tasks.filter(t=>t.due===d)}));}
 else groups=[{name:view==='completed'?'已完成的任务':view==='trash'?'已删除的任务':'待办事项',tasks}];
 const completed=state.tasks.filter(t=>t.completed&&!t.deleted&&(view==='today'?t.due===today:view.startsWith('list:')?t.listId===view.slice(5):true));
 return <div className="task-groups">{groups.map(group=><section className="task-group" key={group.name}><button className={`group-heading ${group.overdue?'overdue':''}`} onClick={()=>setCollapsed({...collapsed,[group.name]:!collapsed[group.name]})}><ChevronDown size={13} className={collapsed[group.name]?'collapsed':''}/><span>{group.name}</span><span className="group-count">{group.tasks.length}</span></button>{!collapsed[group.name]&&group.tasks.map(t=><div key={t.id} className="task-row-wrap"><TaskRow task={t} lists={state.lists} selected={selected===t.id} onSelect={onSelect} toggleTask={toggleTask}/></div>)}</section>)}
 {!tasks.length&&<div className="empty-state"><div className="empty-art"><CheckCheck size={38} strokeWidth={1.2}/></div><h3>{query?'没有找到匹配任务':view==='completed'?'每一个完成，都值得记录':view==='trash'?'这里干干净净': '给今天一点留白'}</h3><p>{query?'试试任务标题、备注或标签中的其他词。':view==='trash'?'删除的任务会保留在这里。':'一切井然有序，下一件想做的事是什么？'}</p>{!['completed','trash'].includes(view)&&<button className="text-button" onClick={newTask}><Plus size={14}/>添加一件小事</button>}</div>}
 {showCompleted&&!['completed','trash'].includes(view)&&completed.length>0&&<section className="task-group completed-group"><div className="group-heading"><CheckCircle2 size={13}/><span>已完成</span><span className="group-count">{completed.length}</span></div>{completed.map(t=><TaskRow key={t.id} task={t} lists={state.lists} selected={selected===t.id} onSelect={onSelect} toggleTask={toggleTask}/>)}</section>}</div>;
}

function TaskDetail({task:t,state,today,updateTask,toggleTask,removeTask,act,setView,close,showToast}){
 const [subtask,setSubtask]=useState(''),[tagEditing,setTagEditing]=useState(false),[tagText,setTagText]=useState('');
 const patch=(data)=>updateTask(t.id,data);
 const list=state.lists.find(l=>l.id===t?.listId),taskActions=useTaskActions();
 return <aside className="detail-panel"><div className="detail-top"><span>{list?<><span className="list-square" style={{'--list-color':list.color}}/>{list.name}</>:<><FileText size={15}/>任务详情</>}</span><IconButton icon={PanelRightClose} label="关闭任务详情" onClick={close}/></div>{!t?<div className="detail-empty"><FileText size={39} strokeWidth={1}/><p>点击任务，查看详情</p><small>把灵感和下一步，都记在这里。</small></div>:<><div className="detail-scroll"><button type="button" className="detail-date" aria-label="快捷设置当前任务日期" onClick={e=>taskActions?.openTaskMenu('date',[t.id],e)}><Calendar size={15}/><span className={t.due&&t.due<today&&!t.completed?'overdue':''}>{t.due?prettyDate(t.due):'添加日期'}</span>{t.repeat!=='none'&&<Repeat2 size={13}/>}<span className="detail-date-dot"/><span>{t.completed?'已完成':t.deleted?'已删除':'进行中'}</span></button>
 <div className="detail-title-row"><button className={`check-box priority-${t.priority} ${t.completed?'checked':''}`} aria-label="切换当前任务完成状态" onClick={()=>toggleTask(t)}>{t.completed&&<Check size={13}/>}</button><textarea aria-label="任务标题" className={`detail-title ${t.completed?'struck':''}`} value={t.title} maxLength={500} rows={Math.max(1,Math.ceil(t.title.length/14))} onChange={e=>{if(e.target.value.trim())patch({title:e.target.value});}}/></div>
 <div className="detail-tags">{t.tags.map(tag=><Badge key={tag}># {tag}</Badge>)}{tagEditing?<form className="tag-edit" onSubmit={e=>{e.preventDefault();const tags=tagText.split(/\s+/).map(v=>v.replace(/^#/,'' )).filter(Boolean);patch({tags:[...new Set(tags)]});setTagEditing(false);}}><input autoFocus aria-label="编辑标签" placeholder="标签用空格分开" value={tagText} maxLength={500} onChange={e=>setTagText(e.target.value)}/><button aria-label="保存标签" type="submit"><Check size={12}/></button></form>:<button className="add-tag" title="添加标签" aria-label="添加标签" onClick={()=>{setTagText(t.tags.join(' '));setTagEditing(true);}}><Plus size={12}/>标签</button>}</div>
 <textarea className="notes-input" aria-label="任务备注" placeholder="添加描述，记录想法或细节…" value={t.notes} maxLength={20000} onChange={e=>patch({notes:e.target.value})} rows={Math.max(4,Math.min(9,t.notes.split('\n').length+1))}/>
 <section className="subtasks"><div className="subtasks-heading"><span>检查事项</span><span>{t.subtasks.filter(s=>s.completed).length} / {t.subtasks.length}</span></div>{t.subtasks.length>0&&<div className="thin-progress"><i style={{width:`${t.subtasks.filter(s=>s.completed).length/t.subtasks.length*100}%`}}/></div>}{t.subtasks.map(s=><div className="subtask-row" key={s.id}><button className={`check-box ${s.completed?'checked':''}`} aria-label={`检查事项 ${s.title}`} onClick={()=>patch({subtasks:t.subtasks.map(v=>v.id===s.id?{...v,completed:!v.completed}:v)})}>{s.completed&&<Check size={11}/>}</button><input aria-label={`编辑检查事项 ${s.title}`} value={s.title} className={s.completed?'struck':''} maxLength={500} onChange={e=>{if(e.target.value.trim())patch({subtasks:t.subtasks.map(v=>v.id===s.id?{...v,title:e.target.value}:v)});}}/><button aria-label={`删除检查事项 ${s.title}`} onClick={()=>patch({subtasks:t.subtasks.filter(v=>v.id!==s.id)})}><X size={12}/></button></div>)}<form className="add-subtask" onSubmit={e=>{e.preventDefault();if(subtask.trim()){patch({subtasks:[...t.subtasks,{id:uid(),title:subtask.trim(),completed:false}]});setSubtask('');}}}><Plus size={14}/><input aria-label="添加检查事项" placeholder="添加检查事项" maxLength={500} value={subtask} onChange={e=>setSubtask(e.target.value)}/>{subtask&&<button type="submit" aria-label="保存检查事项"><ArrowRight size={13}/></button>}</form></section>
 <div className="detail-fields"><label><span><CalendarDays size={15}/>截止日期</span><input type="date" aria-label="截止日期" value={t.due} onChange={e=>patch({due:e.target.value})}/></label><DateShortcuts value={t.due} onChange={due=>patch({due})}/><label><span><Flag size={15}/>优先级</span><select aria-label="任务优先级" value={t.priority} onChange={e=>patch({priority:Number(e.target.value)})}>{PRIORITIES.map((p,i)=><option key={p} value={i}>{p}</option>)}</select></label><label><span><Repeat2 size={15}/>重复</span><select aria-label="重复频率" value={t.repeat} onChange={e=>patch({repeat:e.target.value})}><option value="none">不重复</option><option value="daily">每天</option><option value="weekly">每周</option><option value="monthly">每月</option></select></label><label><span><Layers size={15}/>所属清单</span><select aria-label="所属清单" value={t.listId} onChange={e=>patch({listId:e.target.value})}><option value="inbox">收集箱</option>{state.lists.filter(l=>l.id!=='inbox').map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select></label><label className="important-field"><span><Target size={15}/>重要事项</span><input type="checkbox" aria-label="重要事项" checked={t.important} onChange={e=>patch({important:e.target.checked})}/></label><label className="reminder-field"><span><Bell size={15}/>提醒时间</span><input type="datetime-local" aria-label="提醒时间" value={t.reminder?new Date(new Date(t.reminder).getTime()-new Date(t.reminder).getTimezoneOffset()*60000).toISOString().slice(0,16):''} onChange={e=>patch({reminder:e.target.value?new Date(e.target.value).toISOString():''})}/></label></div><p className="reminder-note"><Bell size={11}/>提醒需应用保持运行，且系统允许通知。</p>
 </div><footer className="detail-footer"><span>创建于 {new Date(t.createdAt).toLocaleDateString('zh-CN',{month:'long',day:'numeric'})}</span><div>{t.deleted?<><IconButton icon={RotateCcw} label="恢复当前任务" onClick={()=>act({type:'TASK_RESTORE',id:t.id})}/><IconButton icon={Trash2} label="永久删除任务" onClick={()=>{if(confirm('永久删除后无法撤销，确定继续？'))act({type:'TASK_PURGE',id:t.id});}}/></>:<><IconButton icon={Timer} label="专注此任务" onClick={()=>{sessionStorage.setItem('shixu-focus-task',t.id);setView('focus');}}/><IconButton icon={Copy} label="复制任务" onClick={()=>{act({type:'TASK_ADD',task:{...t,id:uid(),title:`${t.title}（副本）`,completed:false,completedAt:null,subtasks:t.subtasks.map(s=>({...s,id:uid()}))}});showToast('任务已复制');}}/><IconButton icon={Trash2} label="删除当前任务" onClick={()=>removeTask(t)}/></>}</div></footer></>}</aside>;
}

function NewTaskModal({state,today,defaults,onClose,onAdd}){
 const [data,setData]=useState({title:'',notes:'',due:'',listId:'inbox',priority:0,important:false,repeat:'none',...defaults});
 return <Modal title="新建任务" onClose={onClose}><form className="modal-form" onSubmit={e=>{e.preventDefault();if(data.title.trim())onAdd({...data,title:data.title.trim()});}}><input className="new-title" autoFocus aria-label="新任务标题" placeholder="想做些什么？" required maxLength={500} value={data.title} onChange={e=>setData({...data,title:e.target.value})}/><textarea aria-label="新任务描述" placeholder="添加描述或想法（可选）" rows={4} maxLength={20000} value={data.notes} onChange={e=>setData({...data,notes:e.target.value})}/><div className="form-grid"><label>清单<select aria-label="新任务清单" value={data.listId} onChange={e=>setData({...data,listId:e.target.value})}><option value="inbox">收集箱</option>{state.lists.filter(l=>l.id!=='inbox').map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select></label><label>日期<input type="date" aria-label="新任务日期" value={data.due} onChange={e=>setData({...data,due:e.target.value})}/></label><label>优先级<select aria-label="新任务优先级" value={data.priority} onChange={e=>setData({...data,priority:+e.target.value})}>{PRIORITIES.map((v,i)=><option key={v} value={i}>{v}</option>)}</select></label><label>重复<select aria-label="新任务重复" value={data.repeat} onChange={e=>setData({...data,repeat:e.target.value})}><option value="none">不重复</option><option value="daily">每天</option><option value="weekly">每周</option><option value="monthly">每月</option></select></label></div><DateShortcuts value={data.due} onChange={due=>setData({...data,due})}/><div className="modal-actions"><span>先记录下来，慢慢完成。</span><button type="button" className="secondary" onClick={onClose}>取消</button><button className="primary" type="submit">添加任务<ArrowRight size={14}/></button></div></form></Modal>;
}
function ListModal({item,onClose,onSave,onDelete}){const [name,setName]=useState(item?.name||''),[color,setColor]=useState(item?.color||'#3e63dd');return <Modal title={item?'编辑清单':'新建清单'} onClose={onClose}><form className="modal-form" onSubmit={e=>{e.preventDefault();if(name.trim())onSave({name:name.trim(),color});}}><label>清单名称<input autoFocus required maxLength={80} aria-label="清单名称" placeholder="例如：工作计划、生活灵感" value={name} onChange={e=>setName(e.target.value)}/></label><label>清单颜色</label><div className="color-options">{['#3e63dd','#7255c5','#267d6b','#b27a32','#bd4b69','#777e8a'].map(c=><button key={c} type="button" aria-label={`颜色 ${c}`} className={color===c?'picked':''} style={{background:c}} onClick={()=>setColor(c)}>{color===c&&<Check size={16}/>}</button>)}</div><div className="modal-actions">{item&&<button type="button" className="danger-text" onClick={onDelete}>删除清单</button>}<button type="button" className="secondary" onClick={onClose}>取消</button><button type="submit" className="primary">保存</button></div></form></Modal>;}
function HabitModal({onClose,onSave}){const [name,setName]=useState(''),[target,setTarget]=useState(1),[unit,setUnit]=useState('次');return <Modal title="开始一个好习惯" onClose={onClose}><form className="modal-form" onSubmit={e=>{e.preventDefault();if(name.trim())onSave({name:name.trim(),target:+target,unit,color:'#267d6b'});}}><label>习惯名称<input autoFocus required aria-label="习惯名称" maxLength={80} placeholder="例如：每天阅读" value={name} onChange={e=>setName(e.target.value)}/></label><div className="form-grid"><label>每日目标<input required type="number" aria-label="每日目标" min="1" max="10000" value={target} onChange={e=>setTarget(e.target.value)}/></label><label>单位<input required aria-label="目标单位" maxLength={10} value={unit} onChange={e=>setUnit(e.target.value)}/></label></div><div className="modal-actions"><span>从容易做到的一小步开始。</span><button className="primary" type="submit">创建习惯</button></div></form></Modal>;}
function SearchModal({state,onClose,onSelect,onCommand}){
 const [query,setQuery]=useState(''),[active,setActive]=useState(0);
 const results=selectTasks(state,'all',query).slice(0,30);
 const allCommands=[{id:'new-task',label:'新建任务',keywords:'添加 记录',Icon:Plus},{id:'new-list',label:'新建清单',keywords:'添加 项目',Icon:FolderPlus},{id:'start-focus',label:'开始专注',keywords:'番茄 计时',Icon:Timer},{id:'today',label:'前往今天',keywords:'今天',Icon:Sun},{id:'calendar',label:'前往日历',keywords:'排期',Icon:CalendarDays},{id:'matrix',label:'前往四象限',keywords:'轻重缓急',Icon:Grid2X2},{id:'habits',label:'前往习惯',keywords:'打卡',Icon:Leaf},{id:'settings',label:'打开设置',keywords:'备份 导入 导出',Icon:Settings},{id:'theme',label:document.documentElement.dataset.theme==='dark'?'切换浅色':'切换深色',keywords:'主题 外观',Icon:Layers}];
 const commands=allCommands.filter(c=>!query||`${c.label} ${c.keywords}`.includes(query.trim())).slice(0,query?10:4),entries=[...commands.map(c=>({type:'command',id:c.id})),...results.map(t=>({type:'task',id:t.id}))];
 useEffect(()=>setActive(0),[query]);
 const execute=index=>{const item=entries[index];if(item)item.type==='command'?onCommand(item.id):onSelect(item.id);};
 const handleKey=e=>{if(e.isComposing)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();setActive(index=>{const next=(index+(e.key==='ArrowDown'?1:-1)+entries.length)%Math.max(1,entries.length);requestAnimationFrame(()=>document.getElementById(`command-entry-${next}`)?.scrollIntoView({block:'nearest'}));return next;});}else if(e.key==='Enter'){e.preventDefault();execute(active);}};
 return <Modal title="搜索任务" onClose={onClose} wide><div className="search-modal" onKeyDown={handleKey}><div className="search-modal-input"><Search size={20}/><input autoFocus aria-label="搜索关键词" placeholder="搜索任务，或输入要执行的操作…" value={query} maxLength={500} onChange={e=>setQuery(e.target.value)}/><kbd>↑↓ Enter</kbd></div><div className="search-results">{commands.length>0&&<div className="command-section"><div className="eyebrow">快捷操作</div>{commands.map((c,i)=><button type="button" id={`command-entry-${i}`} className={`command-result ${active===i?'keyboard-active':''}`} key={c.id} onMouseMove={()=>setActive(i)} onClick={()=>onCommand(c.id)}><c.Icon size={16}/><span>{c.label}</span><ArrowRight size={14}/></button>)}</div>}<div className="eyebrow">{query?'搜索结果':'所有待办'} · {results.length}</div>{results.map((t,i)=><button className={`search-result ${active===i+commands.length?'keyboard-active':''}`} id={`command-entry-${i+commands.length}`} key={t.id} onMouseMove={()=>setActive(i+commands.length)} onClick={()=>onSelect(t.id)}><span className={`search-dot priority-${t.priority}`}/><span>{t.title}<small>{state.lists.find(l=>l.id===t.listId)?.name||'收集箱'} {t.due&&`· ${prettyDate(t.due)}`}</small></span><ArrowRight size={15}/></button>)}{!results.length&&!commands.length&&<div className="empty-state"><Search size={30}/><p>没有找到匹配的任务</p></div>}</div></div></Modal>;
}

function BoardView({tasks,lists,selected,onSelect,toggleTask,updateTask}){
 return <div className="board">{[3,2,1,0].map(priority=><section key={priority} className="board-column" onDragOver={e=>{e.preventDefault();e.dataTransfer.dropEffect='move';}} onDrop={e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(tasks.some(t=>t.id===id))updateTask(id,{priority});}}><header><i className={`priority-dot priority-${priority}`}/><b>{PRIORITIES[priority]}</b><span>{tasks.filter(t=>t.priority===priority).length}</span></header>{tasks.filter(t=>t.priority===priority).map(t=><TaskRow key={t.id} task={t} lists={lists} selected={selected===t.id} compact onSelect={onSelect} toggleTask={toggleTask}/>)}<div className="drop-hint">拖入任务调整优先级</div></section>)}</div>;
}
function CalendarView({state,today,onSelect,addTask,updateTask,toggleTask}){
 const [anchor,setAnchor]=useState(today.slice(0,7)+'-01'),[type,setType]=useState('month');
 const [activeDay,setActiveDay]=useState(today),[expandedDay,setExpandedDay]=useState(null); const start=dateAt(anchor);const month=start.getMonth();const year=start.getFullYear();
 const first=shiftDate(anchor,-((start.getDay()+6)%7)); const weekStart=shiftDate(activeDay,-((dateAt(activeDay).getDay()+6)%7));
 const days=Array.from({length:type==='month'?42:7},(_,i)=>shiftDate(type==='month'?first:weekStart,i));
 const move=n=>{if(type==='week'){setActiveDay(shiftDate(activeDay,n*7));}else{const d=new Date(year,month+n,1,12);setAnchor(localDate(d));}};
 const active=state.tasks.filter(t=>!t.completed&&!t.deleted);
 return <div className="calendar-module"><div className="calendar-controls"><h2>{type==='month'?`${year} 年 ${month+1} 月`:prettyDate(weekStart)+' — '+prettyDate(shiftDate(weekStart,6))}</h2><div><div className="segmented"><button className={type==='month'?'active':''} onClick={()=>setType('month')}>月</button><button className={type==='week'?'active':''} onClick={()=>setType('week')}>周</button></div><button className="secondary small" onClick={()=>{setAnchor(today.slice(0,7)+'-01');setActiveDay(today);}}>今天</button><IconButton icon={ChevronLeft} label="上一个周期" onClick={()=>move(-1)}/><IconButton icon={ChevronRight} label="下一个周期" onClick={()=>move(1)}/></div></div><div className="calendar-weekdays">{WEEK.map(d=><span key={d}>周{d}</span>)}</div><div className={`calendar-grid ${type==='week'?'week-view':''}`}>{days.map(day=><div key={day} className={`calendar-day ${day.slice(0,7)!==anchor.slice(0,7)&&type==='month'?'outside':''} ${day===today?'is-today':''}`} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(active.some(t=>t.id===id))updateTask(id,{due:day});}}><div className="calendar-day-number"><span>{+day.slice(-2)}</span><button aria-label={`在 ${day} 添加任务`} onClick={()=>addTask({due:day})}><Plus size={12}/></button></div>{active.filter(t=>t.due===day).slice(0,type==='month'?2:500).map(t=><button key={t.id} draggable onDragStart={e=>e.dataTransfer.setData('text/plain',t.id)} className={`calendar-task priority-${t.priority}`} onClick={()=>onSelect(t.id)}><i/>{t.title}</button>)}{type==='month'&&active.filter(t=>t.due===day).length>2&&<button className="calendar-more" onClick={()=>setExpandedDay(day)}>+{active.filter(t=>t.due===day).length-2} 项更多</button>}</div>)}</div>{expandedDay&&<Modal title={`${prettyDate(expandedDay)}的任务`} onClose={()=>setExpandedDay(null)}><div className="calendar-expanded">{active.filter(t=>t.due===expandedDay).map(t=><TaskRow key={t.id} task={t} lists={state.lists} onSelect={id=>{onSelect(id);setExpandedDay(null);}} toggleTask={toggleTask}/>)}<button className="text-button" onClick={()=>{setExpandedDay(null);addTask({due:expandedDay});}}><Plus size={14}/>添加任务</button></div></Modal>}<p className="module-footnote"><CalendarDays size={13}/>拖动任务到其他日期，即可重新安排。</p></div>;
}
function MatrixView({state,today,onSelect,toggleTask,updateTask}){
 const tasks=state.tasks.filter(t=>!t.completed&&!t.deleted);
 const quads=[{name:'重要且紧急',sub:'现在就做',important:true,urgent:true,color:'#c65c5e'},{name:'重要不紧急',sub:'安排时间',important:true,urgent:false,color:'#b48736'},{name:'紧急不重要',sub:'高效处理',important:false,urgent:true,color:'#527eb2'},{name:'不紧急不重要',sub:'适当留白',important:false,urgent:false,color:'#5e9287'}];
 return <div className="matrix-grid">{quads.map((q,i)=>{const items=tasks.filter(t=>t.important===q.important&&!!(t.due&&t.due<=today)===q.urgent);return <section key={q.name} className="quadrant" style={{'--quad':q.color}} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(!tasks.some(t=>t.id===id))return;const t=tasks.find(t=>t.id===id);updateTask(id,{important:q.important,due:q.urgent?(t.due&&t.due<=today?t.due:today):(t.due&&t.due>today?t.due:'')});}}><header><div><span className="quad-index">0{i+1}</span><h2>{q.name}</h2><p>{q.sub}</p></div><b>{items.length}</b></header><div className="quad-tasks">{items.map(t=><TaskRow key={t.id} task={t} lists={state.lists} onSelect={onSelect} toggleTask={toggleTask} compact/>)}{!items.length&&<div className="quad-empty">将任务拖到这里</div>}</div></section>;})}<p className="matrix-note">“紧急”指截止日期为今天或已逾期；“重要”可在任务详情中设置。</p></div>;
}
function HabitsView({state,today,act,openModal}){
 const days=Array.from({length:7},(_,i)=>shiftDate(today,i-6));const complete=state.habits.filter(h=>(h.history[today]||0)>=h.target).length;
 const streak=h=>{let count=0,date=(h.history[today]||0)>=h.target?today:shiftDate(today,-1);for(let i=0;i<3660;i++){if((h.history[date]||0)<h.target)break;count++;date=shiftDate(date,-1);}return count;};
 return <div className="habits-module"><div className="habit-summary"><div><span className="eyebrow">TODAY'S LITTLE WINS</span><h2>让坚持，慢慢成为日常。</h2><p>今天已完成 <b>{complete}</b> / {state.habits.length} 个习惯</p></div><div className="habit-summary-ring" style={{'--progress':`${state.habits.length?complete/state.habits.length*100:0}%`}}><span><Leaf size={25}/></span></div></div><div className="section-toolbar"><h2>我的习惯<span>{state.habits.length}</span></h2><button className="text-button" onClick={()=>openModal({type:'habit'})}><Plus size={15}/>新建习惯</button></div><div className="habit-table"><div className="habit-table-header"><span>每天进步一点点</span>{days.map(d=><span key={d} className={d===today?'today-text':''}>周{WEEK[(dateAt(d).getDay()+6)%7]}<small>{+d.slice(-2)}</small></span>)}<span>今日</span></div>{state.habits.map((h,i)=><div className="habit-table-row" key={h.id}><div className="habit-name"><span className="habit-icon" style={{color:h.color,background:`${h.color}12`}}>{i%4===0?<BookOpen size={20}/>:i%4===1?<Coffee size={20}/>:i%4===2?<Flame size={20}/>:<Leaf size={20}/>}</span><div><b>{h.name}</b><small><Flame size={11}/>连续 {streak(h)} 天 · 每天 {h.target} {h.unit}</small></div></div>{days.map(d=><button key={d} aria-label={`${h.name} ${d} ${h.history[d]>=h.target?'取消打卡':'打卡'}`} className={`habit-cell ${(h.history[d]||0)>=h.target?'done':''} ${d===today?'is-today':''}`} style={{'--habit':h.color}} onClick={()=>act({type:'HABIT_CHECK',id:h.id,date:d,delta:(h.history[d]||0)>=h.target?-h.target:h.target-(h.history[d]||0)})}>{(h.history[d]||0)>=h.target?<Check size={16}/>:<span/>}</button>)}<div className="habit-count"><button aria-label={`减少 ${h.name}`} disabled={!(h.history[today]>0)} onClick={()=>act({type:'HABIT_CHECK',id:h.id,date:today,delta:-1})}>−</button><span>{h.history[today]||0}<small>/{h.target}</small></span><button aria-label={`增加 ${h.name}`} onClick={()=>act({type:'HABIT_CHECK',id:h.id,date:today,delta:1})}>+</button><button className="habit-delete" aria-label={`删除习惯 ${h.name}`} onClick={()=>{if(confirm('删除此习惯及打卡记录？'))act({type:'HABIT_DELETE',id:h.id});}}><Trash2 size={12}/></button></div></div>)}</div>{!state.habits.length&&<div className="empty-state"><Leaf size={36}/><h3>从一个小习惯开始</h3><button className="primary" onClick={()=>openModal({type:'habit'})}>添加习惯</button></div>}<p className="module-footnote"><Leaf size={13}/>点击日期打卡，再次点击可取消。每一次坚持都值得被看见。</p></div>;
}

function FocusView({state,now,act,showToast,timer,setTimer}){
 const tasks=state.tasks.filter(t=>!t.completed&&!t.deleted),settings=state.settings;
 const [kind,setKind]=useState(timer?.kind||'focus'),[taskId,setTaskId]=useState(()=>{const id=timer?.taskId||sessionStorage.getItem('shixu-focus-task')||'';return tasks.some(t=>t.id===id)?id:'';});
 const [customMinutes,setCustomMinutes]=useState(settings.focusMinutes);
 const total=timer?.total||((kind==='focus'?customMinutes:settings.breakMinutes)*60);
 const remaining=timer?(timer.endAt?Math.max(0,Math.ceil((timer.endAt-now.getTime())/1000)):timer.remaining):total;
 const running=!!timer?.endAt;
 const start=()=>{if(timer&&!running){setTimer({...timer,endAt:Date.now()+timer.remaining*1000});return;}const duration=(kind==='focus'?customMinutes:settings.breakMinutes)*60;setTimer({id:uid(),kind,taskId:taskId||null,total:duration,remaining:duration,endAt:Date.now()+duration*1000});};
 const pause=()=>setTimer({...timer,remaining,endAt:null});
 const stop=()=>{if(running&&!confirm('结束这一段专注？未完成的时间不会计入记录。'))return;setTimer(null);};
 const today=localDate(now),sessions=state.focusSessions.filter(s=>localDate(new Date(s.endedAt))===today),minutes=sessions.reduce((a,s)=>a+s.minutes,0);
 const displaySeconds=Math.max(0,remaining); const pct=(total-displaySeconds)/total*100;
 return <div className="focus-module"><div className="focus-tabs segmented"><button disabled={!!timer} className={kind==='focus'?'active':''} onClick={()=>setKind('focus')}><Timer size={14}/>番茄专注</button><button disabled={!!timer} className={kind==='break'?'active':''} onClick={()=>setKind('break')}><Coffee size={14}/>短暂休息</button></div><div className="focus-ring" style={{'--progress':`${pct}%`}}><div><span className="eyebrow">{running?'STAY IN YOUR FLOW':timer?'TAKE YOUR TIME':'ONE THING AT A TIME'}</span><strong aria-live="off">{String(Math.floor(displaySeconds/60)).padStart(2,'0')}<span>:</span>{String(displaySeconds%60).padStart(2,'0')}</strong><p>{running?'此刻，只专注于这一件事':timer?'已暂停，准备好再继续':'让注意力，回到当下'}</p></div></div><div className="focus-task-picker"><span><Target size={14}/>关联任务</span><select aria-label="专注关联任务" disabled={!!timer} value={taskId} onChange={e=>{setTaskId(e.target.value);sessionStorage.setItem('shixu-focus-task',e.target.value);}}><option value="">自由专注，不关联任务</option>{tasks.map(t=><option key={t.id} value={t.id}>{t.title}</option>)}</select></div>{!timer&&kind==='focus'&&<div className="duration-options">{[15,25,45,60].map(n=><button key={n} className={customMinutes===n?'active':''} onClick={()=>setCustomMinutes(n)}>{n} 分钟</button>)}</div>}<div className="focus-actions"><button className="primary focus-start" onClick={running?pause:start}>{running?<Pause size={17}/>:<Play size={17} fill="currentColor"/>}{running?'暂停':timer?'继续专注':kind==='focus'?'开始专注':'开始休息'}</button>{timer&&<IconButton icon={Square} label="结束计时" onClick={stop}/>}</div><div className="focus-stats"><div><span><Flame size={15}/>今日专注</span><strong>{minutes}<small>分钟</small></strong></div><div><span><CheckCircle2 size={15}/>完成番茄</span><strong>{sessions.length}<small>个</small></strong></div><div><span><Clock size={15}/>累计专注</span><strong>{Math.round(state.focusSessions.reduce((a,s)=>a+s.minutes,0)/60*10)/10}<small>小时</small></strong></div></div>{sessions.length>0&&<div className="focus-history"><h3>今日记录</h3>{[...sessions].reverse().map(s=><div key={s.id}><CheckCircle2 size={14}/><span>{state.tasks.find(t=>t.id===s.taskId)?.title||'自由专注'}</span><small>{s.minutes} 分钟 · {new Date(s.endedAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</small></div>)}</div>}</div>;
}

function SettingsModal({state,act,onClose,showToast,onImport}){
 const [dataPath,setDataPath]=useState('浏览器本地存储'),[busy,setBusy]=useState(false),[error,setError]=useState('');
 useEffect(()=>{desktop?.dataPath().then(setDataPath).catch(e=>setError(e.message));},[]);
 const importBackup=async()=>{setBusy(true);setError('');try{const data=await importState();if(!data)return;const valid=validateState(data);if(confirm(`将恢复 ${valid.tasks.length} 条任务、${valid.habits.length} 个习惯，并替换当前内容。建议先导出当前备份。继续吗？`))onImport(valid);}catch(e){setError(`恢复失败：${e.message}`);}finally{setBusy(false);}};
 return <Modal title="偏好设置" onClose={onClose} wide><div className="settings-content"><section><h3>外观</h3><div className="setting-row"><div><b>界面主题</b><small>选择适合你的工作氛围</small></div><select aria-label="界面主题" value={state.settings.theme} onChange={e=>act({type:'SETTINGS_UPDATE',patch:{theme:e.target.value}})}><option value="light">浅色</option><option value="dark">深色</option><option value="system">跟随系统</option></select></div><div className="setting-row"><div><b>强调色</b><small>少一点干扰，多一点专注</small></div><div className="accent-options">{Object.entries(PALETTES).map(([id,c])=><button key={id} aria-label={`强调色 ${id}`} style={{background:c}} onClick={()=>act({type:'SETTINGS_UPDATE',patch:{accent:id}})}>{state.settings.accent===id&&<Check size={13}/>}</button>)}</div></div></section><section><h3>专注</h3><div className="setting-row"><label htmlFor="focus-duration"><b>默认专注时长</b><small>修改后下次进入专注页生效</small></label><span><input id="focus-duration" aria-label="默认专注时长" type="number" min="1" max="180" value={state.settings.focusMinutes} onChange={e=>{const value=+e.target.value;if(value>=1&&value<=180)act({type:'SETTINGS_UPDATE',patch:{focusMinutes:value}});}}/> 分钟</span></div><div className="setting-row"><label htmlFor="break-duration"><b>休息时长</b></label><span><input id="break-duration" aria-label="休息时长" type="number" min="1" max="60" value={state.settings.breakMinutes} onChange={e=>{const value=+e.target.value;if(value>=1&&value<=60)act({type:'SETTINGS_UPDATE',patch:{breakMinutes:value}});}}/> 分钟</span></div></section><section><h3>数据与备份</h3><div className="storage-note"><ShieldCheck size={20}/><div><b>你的数据，保存在你的电脑上。</b><p>任务、习惯和专注记录仅在本机保存。建议定期导出备份。</p><code>{dataPath}</code></div></div><div className="backup-actions"><button className="secondary" disabled={busy} onClick={async()=>{setBusy(true);try{if(await exportState(state))showToast('备份已导出');}catch(e){setError(e.message);}finally{setBusy(false);}}}><Download size={15}/>导出备份</button><button className="secondary" disabled={busy} onClick={importBackup}><Upload size={15}/>恢复备份</button></div>{error&&<p className="inline-error" role="alert">{error}</p>}</section><section className="about-setting"><span className="brand-mark"><CheckCheck size={19}/></span><div><b>拾序 <span>{appInfo.version}</span></b><small>参考滴答清单功能结构的独立本地实现。<br/>支持任务、日历、四象限、习惯和专注；暂不提供云同步、多人协作、第三方集成及原版订阅服务。</small></div></section></div></Modal>;
}
